def validate_story_start_path_21_30() -> None:
    quests=STORY_START_PATH_21_30
    if len(quests)!=10 or [q.number for q in quests]!=list(range(21,31)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='start_path_020_patrol_knew': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=3 or quest.location_id!='start_path': raise ValueError('invalid_level_or_location')
        if quest.reward_exp!=42 or abs(quest.reward_gold-0.65)>1e-9: raise ValueError('invalid_reward_parity')

validate_story_start_path_21_30()
